python
def ribbonRunsEvenKeyCensus(line, k):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return sum(x%2==0 for x in out)


